const AWS = require('aws-sdk');
const crypto = require('crypto');
const express = require('express');
const app = express();

// Lambda function for token signing and user role management
const kmsClient = new AWS.KMS({ region: process.env.AWS_REGION });
const dynamodb = new AWS.DynamoDB.DocumentClient();

const KEY_ID = process.env.KMS_KEY_ID;
const SIGNING_ALGORITHM = 'RSASSA_PKCS1_V1_5_SHA_256';

async function signToken(payload) {
  const message = Buffer.from(JSON.stringify(payload));
  const params = {
    KeyId: KEY_ID,
    Message: message,
    MessageType: 'RAW',
    SigningAlgorithm: SIGNING_ALGORITHM
  };
  const result = await kmsClient.sign(params).promise();
  return result.Signature.toString('base64');
}

async function verifyToken(payload, signature) {
  const message = Buffer.from(JSON.stringify(payload));
  const params = {
    KeyId: KEY_ID,
    Message: message,
    MessageType: 'RAW',
    Signature: Buffer.from(signature, 'base64'),
    SigningAlgorithm: SIGNING_ALGORITHM
  };
  const result = await kmsClient.verify(params).promise();
  return result.SignatureValid;
}

// Role elevation endpoint - used by admin console
app.post('/api/elevate-role', async (req, res) => {
  try {
    const { userId, targetRole, requestToken, requestSignature } = req.body;

    // Verify the request token signature
    const tokenValid = await verifyToken(requestToken, requestSignature);
    if (!tokenValid) {
      return res.status(403).json({ error: 'Invalid request signature' });
    }

    // VULNERABILITY: The requestToken's role claim is not checked against
    // the actual requester's permissions. Any valid signed token can
    // elevate any user to any role, including 'admin'.
    // An attacker with any valid signed token (e.g., from a low-priv session)
    // can replay it to elevate their own role.

    const updateParams = {
      TableName: 'UserRoles',
      Key: { userId: userId },
      UpdateExpression: 'SET #role = :role, #updatedAt = :now',
      ExpressionAttributeNames: { '#role': 'role', '#updatedAt': 'updatedAt' },
      ExpressionAttributeValues: {
        ':role': targetRole,
        ':now': new Date().toISOString()
      }
    };

    await dynamodb.update(updateParams).promise();

    // Sign a new elevated token for the user
    const newPayload = { userId, role: targetRole, iat: Date.now() };
    const newSignature = await signToken(newPayload);

    return res.json({
      success: true,
      token: { payload: newPayload, signature: newSignature }
    });
  } catch (err) {
    console.error('Elevation error:', err);
    return res.status(500).json({ error: 'Internal error' });
  }
});

